from __future__ import annotations

import asyncio
import sys
from pathlib import Path
from types import SimpleNamespace

import polars as pl
import pytest
from pydantic_ai.messages import ModelMessage, ModelRequest, ModelResponse, TextPart, ToolCallPart, UserPromptPart
from pydantic_ai.models.function import AgentInfo, FunctionModel
from pydantic_ai.models.test import TestModel

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

import ds.data  # noqa: E402
from ui import inline_edit  # noqa: E402
from ui.shortcuts import Shortcut, codemirror_key, sql_keys  # noqa: E402

DB = ds.data.init_db()


def answering(code: str, calls: list[list[ModelMessage]]) -> FunctionModel:
    """A stand-in model that always proposes `code` and records what each request sent.

    (Not capture_run_messages: edit() has its own, and the innermost capture takes the run.)
    """

    def respond(messages: list[ModelMessage], info: AgentInfo) -> ModelResponse:
        calls.append(list(messages))
        return ModelResponse(parts=[ToolCallPart(info.output_tools[0].name, {"code": code})])

    return FunctionModel(respond)


def test_context_shows_how_the_data_is_written(monkeypatch: pytest.MonkeyPatch) -> None:
    """A prompt with "nair" once got `move in ('nair', 'dair')`: only column names were sent"""
    monkeypatch.setattr(inline_edit, "find_session", lambda _token: SimpleNamespace(db=DB, namespace={}))
    for language in ("python", "sql"):
        text = inline_edit.context(language, "t", None)
        assert "nair = 'Neutral Air'" in text
        assert "Frame data values are strings" in text
        assert "- framedata(char_id String" in text
        assert '"char_id": "banjo_and_kazooie"' in text  # first rows of a table


def test_alt_a_is_spelled_for_codemirror() -> None:
    # CodeMirror reads "Alt-A" as Alt+Shift+A, so the letter must be lower case
    assert codemirror_key(Shortcut.INLINE_EDIT) == "Alt-a"
    assert codemirror_key(Shortcut.RUN) == "Mod-Enter"
    assert sql_keys()["inlineEdit"] == "Alt-a"


def test_prompt_marks_the_selection() -> None:
    text = inline_edit.prompt("select ", "*", " from char", "only the name")
    assert "select <selection>*</selection> from char" in text
    assert "replaces the part between <selection>" in text
    assert "Instruction: only the name" in text


def test_prompt_without_selection_rewrites_all_and_carries_the_last_proposal() -> None:
    text = inline_edit.prompt("x =", "", " 1", "make it 2", previous="x = 3")
    assert "<selection>" not in text
    assert "x = 1" in text
    assert "whole new content" in text
    assert "x = 3" in text


def test_sql_context_lists_the_tables() -> None:
    text = inline_edit.context("sql", "", {"char": ["id", "name"]})
    assert "polars SQL" in text
    assert "- char(id, name)" in text


def test_variables_show_dataframes_with_columns() -> None:
    namespace = {"__name__": "__main__", "pl": pl, "r1": pl.DataFrame({"a": [1, 2]}), "n": 3, "_": None}
    text = inline_edit._variables(namespace)
    assert "- r1: polars DataFrame 2 x 1(a Int64)" in text
    assert '{"a": 1}' in text  # its first rows: how the values are written
    assert "- n: int" in text
    assert "pl" not in text.replace("polars", "")


def test_edit_returns_the_models_code() -> None:
    body = {"language": "sql", "before": "select 1", "instruction": "add a column", "schema": {"char": ["id"]}}
    with inline_edit.edit_agent.override(model=TestModel(custom_output_args={"code": "select 1, 2"})):
        answer = asyncio.run(inline_edit.edit(body))
    assert answer["code"] == "select 1, 2"
    # what the call used, for the box's status line (session.TurnUsage.summary)
    assert answer["usage"].endswith("1 request")


def test_edit_needs_an_instruction() -> None:
    assert "error" in asyncio.run(inline_edit.edit({"before": "x", "instruction": "  "}))


def test_inline_key_is_alt_a() -> None:
    assert codemirror_key(Shortcut.INLINE_EDIT) == "Alt-a"


def test_chat_history_goes_along_and_the_cost_is_added(monkeypatch: pytest.MonkeyPatch) -> None:
    history = [ModelRequest(parts=[UserPromptPart("who is ranked first?")]), ModelResponse(parts=[TextPart("Sonix")])]
    session = SimpleNamespace(ai_history=history, db=DB, namespace={}, ai_cost=0.0)
    monkeypatch.setattr(inline_edit, "find_session", lambda _token: session)
    body = {"language": "sql", "before": "select 1", "instruction": "that player", "token": "t"}
    calls: list[list[ModelMessage]] = []
    with inline_edit.edit_agent.override(model=answering("x", calls)):
        asyncio.run(inline_edit.edit(body))
    assert calls[0][: len(history)] == history
    # the stand-in model has no price: the session's total stays (unpriced requests don't add)
    assert session.ai_cost == 0.0


def test_a_whole_proposal_is_checked_before_it_is_shown() -> None:
    sql = inline_edit.EditRun(language="sql", whole=True, db=DB)
    assert inline_edit.proposal_problem(sql, "select * from char limit 2;") == ""
    assert "fails in polars SQL" in inline_edit.proposal_problem(sql, "select nope from char")
    assert "returns no rows" in inline_edit.proposal_problem(sql, "select * from framedata where move = 'nair'")
    python = inline_edit.EditRun(language="python", whole=True)
    assert inline_edit.proposal_problem(python, "x = [1, 2]") == ""
    assert "not valid Python" in inline_edit.proposal_problem(python, "x = [1, 2")
    # a replacement for a selection is a fragment: nothing to check
    assert inline_edit.proposal_problem(inline_edit.EditRun(language="sql", whole=False, db=DB), "nope from") == ""


def test_a_failing_proposal_goes_back_to_the_model_then_is_shown_anyway(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(
        inline_edit, "find_session", lambda _token: SimpleNamespace(ai_history=[], db=DB, namespace={}, ai_cost=0.0)
    )
    body = {"language": "sql", "before": "", "instruction": "anything", "token": "t"}
    calls: list[list[ModelMessage]] = []
    with inline_edit.edit_agent.override(model=answering("select nope from char", calls)):
        answer = asyncio.run(inline_edit.edit(body))
    assert answer["code"] == "select nope from char"
    # asked once, then once more per fix; each time the model is told what failed
    assert len(calls) == inline_edit.MAX_FIXES + 1
    told = [str(part.content) for message in calls[-1] for part in message.parts if part.part_kind != "tool-call"]
    assert sum("fails in polars SQL" in text for text in told) == inline_edit.MAX_FIXES
